from itertools import product
import heapq


def _interval_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_ids = None
        best_value = None

        for chosen in product((0, 1), repeat=len(jobs)):
            if sum(chosen) != k:
                continue
            selected = [job for job, flag in zip(jobs, chosen) if flag]
            ids = {job["id"] for job in selected}
            if not mandatory.issubset(ids) or ids & blocked:
                continue
            counts = {}
            for job in selected:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            valid = True
            for point in {job["start"] for job in selected}:
                if sum(job["start"] <= point < job["end"]
                       for job in selected) > capacity:
                    valid = False
                    break
            if not valid:
                continue
            names = tuple(sorted(ids))
            value = sum(job["value"] for job in selected)
            if (best_ids is None or value > best_value or
                    (value == best_value and
                     (names > best_ids if tie == "largest" else names < best_ids))):
                best_ids, best_value = names, value

        if best_ids is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(n, d):
        if mode == "half_up":
            return (n + d // 2) // d
        return n // d

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(raw * event.get("tax_bp", 0), 10000)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        account = event.get("account", "default")
        currency = event.get("currency", "USD")
        key = account + "|" + currency
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    choices = []
    for name in names:
        rows = [row for row in packages[name]
                if row["version"] not in blocked.get(name, []) and
                (name not in pins or row["version"] == pins[name])]
        choices.append([None] + rows)

    best_vector = None
    best = None
    for assignment in product(*choices):
        installed = {name: row for name, row in zip(names, assignment)
                     if row is not None}
        if any(name not in installed or
               not low <= installed[name]["version"] <= high
               for name, (low, high) in roots.items()):
            continue

        edges = {}
        reachable = set()
        pending = list(roots)
        valid = True
        while pending and valid:
            name = pending.pop()
            if name in reachable:
                continue
            reachable.add(name)
            row = installed.get(name)
            if row is None:
                valid = False
                break
            active = [dep for dep in row.get("deps", [])
                      if not dep.get("feature") or dep.get("feature") in features]
            edges[name] = []
            for dep in active:
                other = dep["name"]
                target = installed.get(other)
                if target is None or not dep["min"] <= target["version"] <= dep["max"]:
                    valid = False
                    break
                edges[name].append(other)
                pending.append(other)
        if not valid or reachable != set(installed):
            continue

        done, active_path = set(), set()
        def visit(name):
            if name in active_path:
                return False
            if name in done:
                return True
            active_path.add(name)
            if any(not visit(other) for other in edges.get(name, [])):
                return False
            active_path.remove(name)
            done.add(name)
            return True

        if not all(visit(name) for name in installed):
            continue
        vector = tuple(installed[name]["version"] if name in installed else -1
                       for name in names)
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best = {name: row["version"] for name, row in installed.items()}

    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _routes(data):
    required = data.get("required", [])
    full = (1 << len(required)) - 1
    source = data["source"]
    initial_mask = sum(1 << i for i, node in enumerate(required) if node == source)
    start_state = (source, initial_mask, data["coupons"])
    distances = {start_state: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if arrival != distances.get(state):
            continue
        if node == data["target"] and mask == full and remaining == 0:
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            outcomes = [(edge["duration"], remaining)]
            if remaining:
                outcomes.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            for duration, next_remaining in outcomes:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                nxt = edge["v"]
                next_mask = mask
                for i, required_node in enumerate(required):
                    if nxt == required_node:
                        next_mask |= 1 << i
                next_state = (nxt, next_mask, next_remaining)
                if next_time < distances.get(next_state, float("inf")):
                    distances[next_state] = next_time
                    heapq.heappush(queue, (next_time, nxt, next_mask, next_remaining))
    return {"arrival": None}


SOLVERS = {
    "component_01": _interval_solver(2, "largest"),
    "component_02": _interval_solver(1, "smallest"),
    "component_03": _interval_solver(2, "smallest"),
    "component_04": _interval_solver(1, "largest"),
    "component_05": _interval_solver(2, "largest"),
    "component_06": _ledger,
    "component_07": _dependencies,
    "component_08": _routes,
}
